import{_ as r}from"./chunks/0c32175a0d0d6b6db9ea.BnJw4KYW.js";import{_ as o,C as a,o as l,c as s,j as e,a as i,E as n,a6 as h}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"这就是你的生活如此糟糕的原因（如何重塑自我）","description":"","frontmatter":{"title":"这就是你的生活如此糟糕的原因（如何重塑自我）","originalTitle":"This Is Why Your Life Sucks (How To Reinvent Yourself)","date":"2023-10-13","originalUrl":"https://thedankoe.com/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself/","minutes":12,"sourceHash":"f238ffaac00411db8c9e1289cf473596ed1b3a3f7b195fbfb69f8efcbb5879f0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself/"}]]},"headers":[],"relativePath":"letters/this-is-why-your-life-sucks-how-to-reinvent-yourself.md","filePath":"letters/this-is-why-your-life-sucks-how-to-reinvent-yourself.md"}'),c={name:"letters/this-is-why-your-life-sucks-how-to-reinvent-yourself.md"};function f(u,p,m,d,b,k){const t=a("ArticleMeta");return l(),s("div",null,[p[0]||(p[0]=e("h1",{id:"这就是你的生活如此糟糕的原因-如何重塑自我",tabindex:"-1"},[i("这就是你的生活如此糟糕的原因（如何重塑自我） "),e("a",{class:"header-anchor",href:"#这就是你的生活如此糟糕的原因-如何重塑自我","aria-label":'Permalink to "这就是你的生活如此糟糕的原因（如何重塑自我）"'},"​")],-1)),n(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/SKI8FcKXQkg?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我经常想起我人生中最黑暗的时期之一。</p><p>有趣的是，当时我并不知道那是我最黑暗的时期。</p><p>在那时，那就是正常状态。</p><p>那就是我的标准。</p><p>我那时的“好”日子，是我现在的糟糕日子……而那时，这却是正常的。</p><p>很多人根本不知道自己本可以感觉多好。他们没意识到，自己的“正常”状态其实是垫底状态。</p><p>我曾经每天早上10点才起床。</p><p>我会直接开车去麦当劳买两个香肠鸡蛋芝士麦满分，配一杯冰咖啡。</p><p>我会立刻感觉自己像垃圾一样，然后躺回床上，一集接一集地看《办公室》，直到我又饿了。</p><p>那时我在上网课。当然，我根本不知道如何管理自己。我把网课的“自由”当作借口，养成了自我毁灭的习惯，慢慢地在自己那舒适的洞穴里等死。</p><p>我几乎不做作业。</p><p>我会在最后一分钟登录，完成最低限度的作业（结果我还拿了A和B）。</p><p>到了晚上，我会花5到7个小时玩《英雄联盟》。有没有朋友一起，都无所谓。那时的我只是在麻痹自己的大脑。</p><p>讲这些，只是为了说明一点：</p><p>电子游戏和真实生活之间的区别，在于假的风险和真的风险。</p><p>真正的痛苦。<br> 真正的恐惧。<br> 真正的牺牲。<br> 正是这些东西，使快乐、爱与成果得以存在。</p><p>在电子游戏里，你可以失败而不承担任何后果。</p><p>但在生活中，你无法只是躲在屏幕后面，寄望着失败不会发生。</p><p>在电子游戏里，我们欺骗自己的大脑，让它以为自己在取得进步。</p><p>而我在生活中，做的正是同样的事。</p><p>睡懒觉、吃快餐、刷网飞——这些让我一直处于多巴胺的滴灌式麻醉之中，让我感觉不到追求更大目标的必要性。</p><p>一切都还“还好”，因为我允许它还好。</p><p>我的生活很糟糕，因为我允许它糟糕。</p><p>在开始之前，《专注的艺术》纪念版盒装书现已开放预售：</p><p><img src="'+r+'" alt=""></p><ul><li>纪念精装版——我们只印刷2000本。</li><li>本书的数字下载版，让你第一时间阅读。</li><li>有声书版本，将在录制和上传完成后提供。</li><li>FOCI 规划本，帮助你将理想的未来拆解为优先任务。</li><li>FOCI 硬币，提醒你带着意图行动。</li><li>数字化转型中心，提供12小时的现代创业培训。</li><li>私密社群，用于更新信息、讨论和建立人脉。</li><li>受邀参加为期两个周末、有6位以上演讲者的“未来工作”线上活动。</li></ul><p>在发售日之前，价格将上涨两次。<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">点击这里预购你的一份。</a></p><h2 id="微小的选择" tabindex="-1">微小的选择 <a class="header-anchor" href="#微小的选择" aria-label="Permalink to &quot;微小的选择&quot;">​</a></h2><p>你的生活如此糟糕，是因为过去一年里你做出的那成千上万个微小选择。</p><p>你没有做出那些通向有目标事业的选择。</p><p>你没有做出那些通向充实关系的选择。</p><p>你没有做出那些通向健康且好看身体的选择。</p><p>“但是丹，那基因怎么说？我出生的地方怎么说？我做的这份没给我留出足够时间的工作又怎么说，等等等等……”</p><p>没错，这些因素确实起作用。</p><p>但你刚刚又做出了另一个微小的选择——把自己的心智关闭起来，不去思考在你的处境中你<em>能</em>做什么。</p><blockquote><p>选择的能力无法被夺走，甚至无法被送出去——它只能被遗忘。——格雷格·麦基昂（Greg McKeown）</p><p>《精要主义》</p></blockquote><p>看看周围，不难发现，你并非什么特例。有成千上万像你一样的人，已经扭转了自己的处境。</p><p>从现在起一年后，你生活的质量将取决于那些不断累积、最终构成那种生活的微小选择。</p><p>你不必做出完美的选择。</p><p>实际上，犯错反而更好。</p><p>最大的风险就是完全不承担风险，因为不这样，你又怎么会失败呢？</p><p>没有失败，进步在字面意义上就是不可能的。</p><p>没有进步，你的人生就没有方向。</p><p>没有人生方向，一切都会变得毫无意义。</p><p>成为一个更好的人，就是你活出目标感的方式。</p><h2 id="高标准" tabindex="-1">高标准 <a class="header-anchor" href="#高标准" aria-label="Permalink to &quot;高标准&quot;">​</a></h2><p>穷人对贫穷本身没什么感觉，直到某件灾难性的事情发生。</p><p>而灾难性事件发生在他们身上的概率也确实更高。</p><p>他们的车爆了，因为它太旧、缺乏保养。</p><p>有人闯入他们住在治安不好街区里的家。</p><p>他们的父母生病了，而他们因为收入太低而无能为力。</p><p>当然，此时他们会有一些赚钱的动力，但他们觉得灾难发生的时候已经太晚了。他们没有提前准备。</p><p>于是他们陷入了一个无尽的循环，反复念着：“我早该更早开始的。”</p><p>最终，一切又归于平静。他们生活中的压力降低了。他们又开始重新享受那些让人麻木的舒适。等待着下一次灾难把他们再次击垮。</p><p>而成功的人，会利用这些事件来改变自己是谁。</p><p>“你是谁”决定了你的标准与价值观。</p><p>你的标准与价值观，决定了你所做出的那些微小选择。</p><p>如果你能接受银行账户里只有5美元，你就不会把它视为一个问题。</p><p>如果你能接受银行账户里有10万美元，那么任何低于这个数字的情况，你都会视为一个需要解决的问题。</p><p>问题会为你的认知设定框架——我在<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">我的书</a>里谈到过这一点。</p><p>你会开始注意到更多赚钱的机会。</p><p>你在谷歌上搜索的内容，会变成诸如“如何每月额外赚1000美元”之类的东西。</p><p>你会开始和朋友聊起关于钱的话题。</p><p>所有这些微小的选择，都开始累积成结果。</p><p>你会基于自己对当前所面对问题相关的特定信息的有意寻找，重新塑造自己的思维模式。</p><p>你所摄取的信息，会极大地影响你的身份认同，进而影响你的标准。</p><p>如果你让自己身处的环境——无论是现实还是数字世界——中的人都让“超重100斤、一分钱没有、干着自己讨厌的工作、和一个你厌恶的伴侣在一起、每晚喝到断片”之类的事看起来“没什么大不了”，你觉得你的人生最终会走向何处？</p><p>如果你的标准要求你只吃全食超市（Whole Foods）的食物，你看麦当劳的餐食时就会心生厌恶。</p><p>如果你的标准要求你像CEO那样工作，你就会把低层次的苦力活视为一个必须通过技能习得、教育、优先级排序和外包来解决的问题。</p><p>显然，你无法立刻解决生活中所有的问题。</p><p>你现在也无法逃离你的处境。</p><p>你需要一个计划。一个方向。一条出路。</p><p>而坚持这个计划，我向你保证，这段旅程本身会比那件事的结果更让人享受。</p><p>就像尼采说的那样：</p><blockquote><p>“幸福就是那种感觉——力量在增长，阻力正在被克服。”</p></blockquote><h2 id="你想成为的那个人的标准" tabindex="-1">你想成为的那个人的标准 <a class="header-anchor" href="#你想成为的那个人的标准" aria-label="Permalink to &quot;你想成为的那个人的标准&quot;">​</a></h2><p>大多数人对待生活采取的是最低限度的方式。</p><p>快钱、快性、快乐，不承诺、不深入、不失败。</p><p>你越想把生活变得轻松，它就会变得越艰难。</p><p>摆脱这种盲目生活的方式，就是采用你想成为的那个人的标准。</p><p>你想赚多少钱？</p><p>什么样的工作会带给你充实感？</p><p>你理想中的关系是什么样的，无论是朋友还是伴侣？</p><p>你想拥有怎样的外表和感觉？</p><p>你必须超越生存的最低限度。</p><p>承诺让你的行为背后都有一个理由。</p><p>如果你不知道自己为什么在做某件事，那你又为什么在做它？而如果你知道原因，那你为什么还在无视它？</p><p>你是在星巴克递出40杯三倍泵摩卡卡布奇诺来推动人类进步吗？还是在让人类变得肥胖又不健康？</p><p>你为什么还没有开始追求一个更有意义的事业，或者开始创业？</p><p>你知道自己为什么要把食物一股脑塞进嘴里吗？你理解每一种营养物质是如何与你的生理机能互动、构建出一个健康状态的吗？</p><p>你为什么还没有开始学习关于健康与训练的知识？</p><p>你生活在自己的身体里。了解它，本应是你的全职工作。</p><p>你知道自己为什么在和一个当年很容易到手的伴侣敷衍度日吗？你能想象自己再和这个人一起过40年吗？</p><p>你为什么还没有提升自己的社交技巧，让自己能够吸引到更好的伴侣？</p><p>这话说起来很老套，但你在这场人生游戏里，只有一次机会。</p><p>唯一能阻止你过上毫无意义人生的人，就是你自己。</p><h2 id="互联网的力量" tabindex="-1">互联网的力量 <a class="header-anchor" href="#互联网的力量" aria-label="Permalink to &quot;互联网的力量&quot;">​</a></h2><p>让我们来拆解一下，是什么造就了更好的选择：</p><p>学习，是人类最根本的驱动力。</p><p>出生时，你就是一块信息海绵。</p><p>你的父母、朋友、社会、老师和上司，都在把他们的世界观投射到你身上。</p><p>那么，他们的世界观又是从哪来的？来自同样的那些人，除非他们曾质疑过它。</p><p>这就是你所知道的一切。</p><p>如果能给它标个数字，你所知道的信息，还不到这世界上所有可用信息的1%。可能更接近于不到0.001%。</p><p>这些信息在现实中为你创建了参照点。</p><p>这正是你把自己与他人区分开来的方式。</p><p>它塑造了你的身份认同。</p><p>你的身份认同限制了你能注意到哪些信息，因为你所学到的东西本就有限。如果你还没学过那些连接“它是什么”和“你已知道什么”之间的信息，你就不会注意到某些事物。如果你还没学过入门信息，你就无法理解中级信息。你无法从第1级跳到第3级。正因如此，你正在错过99%的人生。</p><p>如果我接触到那些让人变成哥特风的信息和环境，我就会在音乐、人群、穿着、工作机会、对未来的看法以及情绪状态上，注意到某些特定的喜好与厌恶。</p><p>作为一个哥特青年，我不会注意到，甚至根本不会在乎那些可以尝试的、有利可图的商业机会（假设我是那种典型的、厌恶世界的孤僻哥特青年）。</p><p>如果我让自己长期沉浸在某种信息中，以此重新编程我的身份认同，我就会开始发现与那种身份相关的机会。</p><p>这就引出了互联网的力量。</p><p>你可以精心打理一座数字花园，也可能被推入一片数字沼泽。</p><p>我们从未接触过如此海量的信息，而我很难相信，这些信息不会以极快的速度、且往更糟的方向塑造着人们的身份认同。</p><p>当你登录社交媒体时，默认的动作就是去关注那些娱乐性账号和表情包页面。</p><p>几乎所有这些账号，都让你的大脑被那些像开派对一样闯入的“不良房客”所占据，他们把你的大脑当成兄弟会的房子一样狂欢。等“父母”回家时，看到眼前的景象会崩溃。</p><p>而你的“觉察”，就是当那些漫不经心的想法把你的大脑变成一片沼泽之后，父母回家看到的那一刻。</p><p>从现在开始，去意识到这一点。</p><ol><li><strong>取关那些无助于培养你生活中更高标准的账号。</strong> 即便看起来不像那样，也无论你怎样为自己找理由辩解，你所关注的人都在潜移默化地影响着你的行为。慢慢地，然后突然之间，你就变成了一个你自己可能会厌恶的人。</li><li><strong>花时间去关注那些有价值的账号。</strong> 有价值的账号会挑战你的世界观，让你跳出固有框架去思考，并教给你达到更高生活质量所必需的技能。</li></ol><p>这不是一个一夜之间就能完成的过程。</p><p>一开始，你或许不会觉得这些信息有什么用。</p><p>要让那些具体的想法彼此连接、最终形成理解，是需要时间的。</p><p>你可能会觉得这很无聊……直到它变成世界上最有趣的事情之一。</p><p>关注一个账号。</p><p>让算法去发挥作用。</p><p>关注那些回复第一个账号帖子的账号。</p><p>随着时间推移，你会创造出一个有利于你成长的环境。</p><p><em>你和比你更成功的人之间唯一的区别，就是他们在摄取信息背后持续的意图。</em></p><p>“但是行动呢？？？”</p><p>你每天都在行动。</p><p>为什么？</p><p>因为你的大脑已经被那些促成这些行动的信息编程好了。</p><p>你的身份是由你所摄取的信息塑造而成的，仅凭这一点就决定了你会把什么视为可以行动的机会。</p><p>把自己放在正确的人群中，你就能实现任何你想要的东西。</p><h2 id="价值创造者之路" tabindex="-1">价值创造者之路 <a class="header-anchor" href="#价值创造者之路" aria-label="Permalink to &quot;价值创造者之路&quot;">​</a></h2><p>为什么人们一直在做自己讨厌的事情？</p><p>我一直很好奇这个问题。</p><p>倒不是说我是那种从未陷入这个陷阱的特殊小花，而是那种感觉自己已经逃脱、能站在山上更高的地方审视这一切，直到自己不可避免地又跌回原地的人。</p><p>祈祷周末快点到来。</p><p>畏惧周一的早晨。</p><p>隐藏真正的自己，以便和你不喜欢一起工作的人交谈。</p><p>把互联网当作逃避现实的工具。</p><p>刷屏、点击，让大脑再多关闭一会儿，因为当它运转起来时，你并不喜欢它在做的事情。</p><p>这就是消费者的生活。</p><p>是那个被互联网利用的人，而不是利用互联网的人。</p><p>你无法逃避这个新世界。</p><p>你可以对抗它，也可以顺流而行。</p><p>虽然互联网是问题所在，但它同时也是解决方案。</p><p>你不必用互联网来做这件事，但也没有理由不用它。</p><p><em>你生活糟糕的最后一个原因，是你没有为人类做出贡献。</em></p><p><em>你没有为人类做出贡献，是因为你没有那种珍贵到你忍不住要分享的东西。</em></p><p><em>你没有值得提供的东西，是因为你忽视了生活中那些急需解决方案被创造出来的问题。</em></p><p><em>你忽视了生活中的问题，是因为你对如何实现能解决这些问题的目标毫无头绪。</em></p><p><em>你对如何实现目标毫无头绪，是因为你没有可以构建的东西。没有任何东西来框定和引导你的学习。</em></p><p>价值创造者，是那种对自己的输入和输出都怀有意图的人。</p><p>他们把自己的生活当作一个科学项目来对待。</p><p>他们识别出自己的问题。</p><p>他们利用互联网上无穷无尽的资源来教育自己。</p><p>他们在自己身上测试解决方案，并通过写作分享自己的经历。</p><p>他们把最有效、最精简的解决方案打包成产品或服务。</p><p>这就是他们如何通过有目的地生活来谋生的方式。</p><p>成为创作者，是治愈过度消费的良药。</p><p>我在之前的信件中已经多次讨论过这个话题。我也在我的书《<a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">专注的艺术</a>》（The Art Of Focus）中做了详细的拆解。</p><p>写作，是传递价值的载体。</p><p>我在所有平台上写作。我不在乎去和那些晒豪车或炫耀生活方式的照片竞争。我通过把互联网不仅当作整理优质想法的地方，还当作组织和分享这些想法给他人的地方，来获得深深的满足感——而这一切最大的好处，就是靠做自己喜欢的事情为生。这是我能掌控的事情。</p><p>这不是关于变得出名。</p><p>这不是关于建立庞大的粉丝群。</p><p>这是关于把你所拥有的价值传播到一个能触及任何人的地方，从而带来能改变你生活和事业的机会。</p><p>你不需要一门循序渐进的课程，才能加入这场网络盛宴。</p><p>写你想写的东西。</p><p>和你想交谈的人交谈。</p><p>不要做一个隐形人，让你的名字出现在人们面前。</p><p>让人们看到你的文字，这样它才能随着时间越传越广。</p><p>如果你真的需要额外的推动力，只需长时间观察你所关注的那些人。</p><p>观察他们写的内容。</p><p>观察他们是怎么写的。</p><p>观察他们和谁互动。</p><p>观察他们靠卖什么来谋生。</p><p>把这些点连起来，然后开始模仿他们。</p><p>如果你没有答案，就去查。</p><p>你不会立刻得到所有答案。</p><p>接受这一点，没关系。</p><p>如果你知道自己注定要成就更多，那就开始像那样去行动。</p><p>你不必非要写作，但我什么都尝试过了。</p><p>写作作为人类存在以来一直延续下来的最基本的交流方式，是发现你真正想做的事情的绝佳起点。</p><p>祝我的朋友们，度过愉快的一周剩余时光。</p><p>丹·科伊 (Dan Koe)</p><hr><p><a href="/en/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',190))])}const g=o(c,[["render",f]]);export{w as __pageData,g as default};
